# (Buffett 7 câu nói, Lãi kép – Franklin): 15 giây đầu là câu chuyện có thật (năm + người + con số),
# huyền thoại ai cũng biết, giải mã thành quy trình áp dụng ngay, 6–9 phút, câu móc mỗi 60–90 giây.
GOLD = (255, 196, 0); RED = (239, 68, 68); GREEN = (34, 197, 94); BLUE = (56, 189, 248); WHITE = (255, 255, 255)
S = {}
def T(cap, say, anh=None, ch=None, label="", moc=False):
    d = {'k': 'text', 'label': label, 'cap': cap, 'cols': (WHITE, GOLD), 'say': say}
    if anh: d['anh'] = anh
    if ch: d['ch'] = ch
    if moc: d['moc'] = True
    return d
def CL(cap, items, say, ch=None, label=""):
    d = {'k': 'checklist', 'label': label, 'cap': cap, 'cols': (WHITE, GOLD), 'items': [(i, GOLD) for i in items], 'say': say}
    if ch: d['ch'] = ch
    return d
def BN(cap, value, fmt, unit, top, sub, say, ch=None, col=None, moc=False):
    d = {'k': 'bignum', 'label': '', 'cap': cap, 'cols': (WHITE, GOLD), 'value': value, 'fmt': fmt, 'unit': unit, 'top': top, 'sub': sub, 'say': say}
    if ch: d['ch'] = ch
    if col: d['col'] = col
    return d
def END(cap, say): return {'k': 'end', 'label': '', 'cap': cap, 'cols': (WHITE, GOLD), 'say': say}

